#!/bin/sh
# Generated by FWShift: rules for the WAN Firewall and the Internet Firewall of a Cato Networks account, added through
# the GraphQL API with curl. Read the report first: what is not written is listed there and at the end of this file.
# It only adds rules; it changes and removes nothing, and it does not publish: the rules land in an unpublished
# revision, which you review in the Cato Management Application and publish (or discard) yourself.
# Usage: CATO_API_KEY=... CATO_ACCOUNT_ID=12345 [CATO_API_URL=https://api.catonetworks.com/api/v1/graphql2]
#        [CATO_WAN_POSITION=LAST_IN_POLICY] [CATO_WAN_REF=<rule or section id>] [CATO_WAN_REVISION=<revision id>]
#        [CATO_IF_POSITION=LAST_IN_POLICY] [CATO_IF_REF=<rule or section id>] [CATO_IF_REVISION=<revision id>]
#        [DRY_RUN=1] sh this-file
# A position is FIRST_IN_POLICY, LAST_IN_POLICY, FIRST_IN_SECTION, LAST_IN_SECTION, BEFORE_RULE or AFTER_RULE; the ones
# of a section or a rule need its id as the REF. Every rule after the first goes right after the one added before it.
# DRY_RUN=1 only writes the rules, and needs no key. The ids of the rules added are written to created.txt.
set -eu
OUT="${OUT:-cato-$(date +%Y%m%d%H%M%S)}"
mkdir -p "$OUT"
CATO_API_URL="${CATO_API_URL:-https://api.catonetworks.com/api/v1/graphql2}"
CATO_WAN_POSITION="${CATO_WAN_POSITION:-LAST_IN_POLICY}"; CATO_WAN_REF="${CATO_WAN_REF:-}"; CATO_WAN_REVISION="${CATO_WAN_REVISION:-}"
CATO_IF_POSITION="${CATO_IF_POSITION:-LAST_IN_POLICY}"; CATO_IF_REF="${CATO_IF_REF:-}"; CATO_IF_REVISION="${CATO_IF_REVISION:-}"
WAN_PREV=; IF_PREV=
Q_WAN='mutation fwshiftAddRule($accountId: ID!, $policy: WanFirewallPolicyMutationInput, $input: WanFirewallAddRuleInput!) { policy(accountId: $accountId) { wanFirewall(input: $policy) { addRule(input: $input) { rule { rule { id } } status errors { errorCode errorMessage } } } } }'
Q_IF='mutation fwshiftAddRule($accountId: ID!, $policy: InternetFirewallPolicyMutationInput, $input: InternetFirewallAddRuleInput!) { policy(accountId: $accountId) { internetFirewall(input: $policy) { addRule(input: $input) { rule { rule { id } } status errors { errorCode errorMessage } } } } }'
check() {  # check NAME VALUE KIND
  case "$3" in
    position) case "$2" in FIRST_IN_POLICY|LAST_IN_POLICY|FIRST_IN_SECTION|LAST_IN_SECTION|BEFORE_RULE|AFTER_RULE) return 0 ;; esac ;;
    id) case "$2" in *[!A-Za-z0-9_=-]*) ;; *) return 0 ;; esac ;;
  esac
  echo "$1: not a valid value: $2" >&2; exit 1
}
add() {  # add wanFirewall|internetFirewall RULE-FILE: adds one rule after the one added before it, and keeps its id
  if [ "$1" = wanFirewall ]; then q=$Q_WAN; prev=$WAN_PREV; pos=$CATO_WAN_POSITION; ref=$CATO_WAN_REF; rev=$CATO_WAN_REVISION
  else q=$Q_IF; prev=$IF_PREV; pos=$CATO_IF_POSITION; ref=$CATO_IF_REF; rev=$CATO_IF_REVISION; fi
  if [ -n "$prev" ]; then at="{\"position\":\"AFTER_RULE\",\"ref\":\"$prev\"}"
  elif [ -n "$ref" ]; then at="{\"position\":\"$pos\",\"ref\":\"$ref\"}"
  else at="{\"position\":\"$pos\"}"; fi
  if [ -n "$rev" ]; then policy="{\"revision\":{\"id\":\"$rev\"}}"; else policy=null; fi
  { printf '{"query":"%s","variables":{"accountId":"%s","policy":%s,"input":{"at":%s,"rule":' "$q" "$CATO_ACCOUNT_ID" "$policy" "$at"
    cat "$2"; printf '}}}\n'; } > "$OUT/request.json"
  tries=0
  while :; do
    code=$(curl -sS -o "$OUT/last.json" -w '%{http_code}' -X POST -H "x-api-key: $CATO_API_KEY" -H 'Content-Type: application/json' \
           --data-binary @"$OUT/request.json" "$CATO_API_URL")
    case "$code" in
      200) break ;;
      429|502|503) tries=$((tries+1)); [ "$tries" -le 5 ] || { echo "HTTP $code: giving up at $2" >&2; exit 1; }; sleep $((tries*5)) ;;
      *) echo "HTTP $code at $2:" >&2; cat "$OUT/last.json" >&2; exit 1 ;;
    esac
  done
  flat=$(tr -d ' \t\r\n' < "$OUT/last.json")
  case "$flat" in *'"status":"SUCCESS"'*) ;; *) echo "refused at $2:" >&2; cat "$OUT/last.json" >&2; exit 1 ;; esac
  id=$(printf '%s' "$flat" | sed -n 's/.*"rule":{"rule":{"id":"\([^"]*\)"}.*/\1/p')
  [ -n "$id" ] || { echo "no rule id in the answer at $2" >&2; exit 1; }
  echo "$1 $id $2" >> "$OUT/created.txt"
  if [ "$1" = wanFirewall ]; then WAN_PREV=$id; else IF_PREV=$id; fi
}
cat > "$OUT/wan-001.json" <<'FWSHIFT_EOF'
{"name": "fws-block intra-zone DMZ", "description": "zone DMZ blocks traffic between its members (block)", "enabled": true, "action": "BLOCK", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "DMZ"}]}, "destination": {"site": [{"by": "NAME", "input": "DMZ"}]}, "service": {"custom": []}, "tracking": {"event": {"enabled": false}}, "exceptions": []}
FWSHIFT_EOF
cat > "$OUT/wan-002.json" <<'FWSHIFT_EOF'
{"name": "fws-LAN1_Outgoing", "description": "LAN1 to the internet", "enabled": true, "action": "ALLOW", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "LAN1"}]}, "destination": {"site": [{"by": "NAME", "input": "WAN"}]}, "service": {"custom": []}, "tracking": {"event": {"enabled": true}}, "exceptions": [{"source": {"ipRange": [{"from": "0.0.0.0", "to": "10.9.255.255"}, {"from": "10.10.1.0", "to": "10.19.255.255"}, {"from": "10.20.1.0", "to": "10.30.0.9"}, {"from": "10.30.0.11", "to": "10.30.0.24"}, {"from": "10.30.0.26", "to": "255.255.255.255"}]}, "name": "fwshift 1"}, {"destination": {}, "name": "fwshift 2"}]}
FWSHIFT_EOF
cat > "$OUT/wan-003.json" <<'FWSHIFT_EOF'
{"name": "fws-Block_Partner_SSH", "description": "", "enabled": true, "action": "BLOCK", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "WAN"}]}, "destination": {"site": [{"by": "NAME", "input": "DMZ"}]}, "service": {"custom": [{"protocol": "TCP", "port": [22]}]}, "tracking": {"event": {"enabled": true}}, "exceptions": [{"source": {"ipRange": [{"from": "0.0.0.0", "to": "203.0.112.255"}, {"from": "203.0.113.128", "to": "255.255.255.255"}]}, "name": "fwshift 1"}, {"destination": {"ipRange": [{"from": "0.0.0.0", "to": "10.30.0.9"}, {"from": "10.30.0.11", "to": "10.30.0.24"}, {"from": "10.30.0.26", "to": "255.255.255.255"}]}, "name": "fwshift 2"}]}
FWSHIFT_EOF
cat > "$OUT/wan-004.json" <<'FWSHIFT_EOF'
{"name": "fws-WAN_to_Web", "description": "", "enabled": true, "action": "ALLOW", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "WAN"}]}, "destination": {"site": [{"by": "NAME", "input": "DMZ"}]}, "service": {"custom": [{"protocol": "TCP", "port": [80, 443, 8443]}, {"protocol": "TCP", "portRange": {"from": 8080, "to": 8089}}]}, "tracking": {"event": {"enabled": false}}, "exceptions": [{"source": {}, "name": "fwshift 1"}, {"destination": {"ipRange": [{"from": "0.0.0.0", "to": "10.30.0.9"}, {"from": "10.30.0.11", "to": "198.51.100.9"}, {"from": "198.51.100.11", "to": "255.255.255.255"}]}, "name": "fwshift 2"}]}
FWSHIFT_EOF
cat > "$OUT/wan-005.json" <<'FWSHIFT_EOF'
{"name": "fws-WAN_to_Mail", "description": "", "enabled": true, "action": "ALLOW", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "WAN"}]}, "destination": {"site": [{"by": "NAME", "input": "DMZ"}]}, "service": {"custom": [{"protocol": "TCP", "port": [25]}]}, "tracking": {"event": {"enabled": true}}, "exceptions": [{"source": {}, "name": "fwshift 1"}, {"destination": {"ipRange": [{"from": "0.0.0.0", "to": "10.30.0.24"}, {"from": "10.30.0.26", "to": "198.51.100.10"}, {"from": "198.51.100.12", "to": "255.255.255.255"}]}, "name": "fwshift 2"}]}
FWSHIFT_EOF
cat > "$OUT/wan-006.json" <<'FWSHIFT_EOF'
{"name": "fws-Admin_Mgmt", "description": "", "enabled": true, "action": "ALLOW", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "LAN1"}]}, "destination": {"site": [{"by": "NAME", "input": "DMZ"}]}, "service": {"custom": [{"protocol": "TCP", "port": [22, 80, 443, 8443]}, {"protocol": "TCP", "portRange": {"from": 8080, "to": 8089}}]}, "tracking": {"event": {"enabled": false}}, "exceptions": [{"source": {"ipRange": [{"from": "0.0.0.0", "to": "10.10.0.49"}, {"from": "10.10.0.60", "to": "255.255.255.255"}]}, "name": "fwshift 1"}, {"destination": {"ipRange": [{"from": "0.0.0.0", "to": "10.30.0.9"}, {"from": "10.30.0.11", "to": "10.30.0.24"}, {"from": "10.30.0.26", "to": "255.255.255.255"}]}, "name": "fwshift 2"}]}
FWSHIFT_EOF
cat > "$OUT/wan-007.json" <<'FWSHIFT_EOF'
{"name": "fws-LAN1_to_DMZ_Reject", "description": "", "enabled": true, "action": "BLOCK", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "LAN1"}]}, "destination": {"site": [{"by": "NAME", "input": "DMZ"}]}, "service": {"custom": []}, "tracking": {"event": {"enabled": true}}, "exceptions": [{"source": {}, "name": "fwshift 1"}, {"destination": {}, "name": "fwshift 2"}]}
FWSHIFT_EOF
cat > "$OUT/wan-008.json" <<'FWSHIFT_EOF'
{"name": "fws-Alice_Workhours", "description": "", "enabled": false, "action": "ALLOW", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "LAN1"}]}, "destination": {"site": [{"by": "NAME", "input": "WAN"}]}, "service": {"custom": [{"protocol": "TCP", "port": [443]}]}, "tracking": {"event": {"enabled": false}}, "exceptions": [{"source": {}, "name": "fwshift 1"}, {"destination": {}, "name": "fwshift 2"}]}
FWSHIFT_EOF
cat > "$OUT/wan-009.json" <<'FWSHIFT_EOF'
{"name": "fws-VS_Only", "description": "", "enabled": false, "action": "ALLOW", "direction": "TO", "source": {"site": [{"by": "NAME", "input": "WAN"}]}, "destination": {"site": [{"by": "NAME", "input": "DMZ"}]}, "service": {"custom": []}, "tracking": {"event": {"enabled": false}}, "exceptions": [{"source": {}, "name": "fwshift 1"}, {"destination": {}, "name": "fwshift 2"}]}
FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the rules are in $OUT"; exit 0; fi
: "${CATO_API_KEY:?set CATO_API_KEY}"
: "${CATO_ACCOUNT_ID:?set CATO_ACCOUNT_ID}"
case "$CATO_ACCOUNT_ID" in *[!0-9]*) echo "CATO_ACCOUNT_ID: digits" >&2; exit 1 ;; esac
check CATO_WAN_POSITION "$CATO_WAN_POSITION" position; check CATO_IF_POSITION "$CATO_IF_POSITION" position
for v in "$CATO_WAN_REF" "$CATO_IF_REF" "$CATO_WAN_REVISION" "$CATO_IF_REVISION"; do [ -z "$v" ] || check id "$v" id; done
case "$CATO_WAN_POSITION" in *_SECTION|*_RULE) [ -n "$CATO_WAN_REF" ] || { echo "CATO_WAN_POSITION $CATO_WAN_POSITION needs CATO_WAN_REF" >&2; exit 1; } ;; esac
case "$CATO_IF_POSITION" in *_SECTION|*_RULE) [ -n "$CATO_IF_REF" ] || { echo "CATO_IF_POSITION $CATO_IF_POSITION needs CATO_IF_REF" >&2; exit 1; } ;; esac
add wanFirewall "$OUT/wan-001.json"
add wanFirewall "$OUT/wan-002.json"
add wanFirewall "$OUT/wan-003.json"
add wanFirewall "$OUT/wan-004.json"
add wanFirewall "$OUT/wan-005.json"
add wanFirewall "$OUT/wan-006.json"
add wanFirewall "$OUT/wan-007.json"
add wanFirewall "$OUT/wan-008.json"
add wanFirewall "$OUT/wan-009.json"
echo "done: $(wc -l < "$OUT/created.txt" 2>/dev/null || echo 0) rules added; review and publish the revision"
# Not written:
#   Monitor_Ping: its services cannot be written: an ICMP type, ICMPv6, SCTP or another IP protocol: a custom service of Cato is TCP, UDP or ICMP
#   Old_Rule: its services cannot be written: an ICMP type, ICMPv6, SCTP or another IP protocol: a custom service of Cato is TCP, UDP or ICMP
#   DNS_From_Port: its services cannot be written: source ports: a service of Cato has destination ports only
#   Country_Block: 'COUNTRY_X' holds members whose addresses are not known
#   Portal_Access: host names as the destination: Cato takes them as destinations on the internet only
#   ESP_Out: its services cannot be written: an ICMP type, ICMPv6, SCTP or another IP protocol: a custom service of Cato is TCP, UDP or ICMP
#   V6_LAN_Out: no IPv4 address as the source
#   V6_Admin_Web: no IPv4 address as the source
#   V6_Ping: its services cannot be written: an ICMP type, ICMPv6, SCTP or another IP protocol: a custom service of Cato is TCP, UDP or ICMP
